<?php

/* @autogenerated */
declare(strict_types=1);

namespace Civi\Lughauth\Features\Access\UserInvitation\Domain\ValueObject\Holder;

use Civi\Lughauth\Shared\Value\Validation\ConstraintFailList;
use Civi\Lughauth\Features\Access\UserInvitation\Domain\ValueObject\UserInvitationRolesVO;

trait UserInvitationRolesAttributeHolder
{
    protected UserInvitationRolesVO|string|null $roles = null;
    protected bool $rolesAssigned = false;

    public function getRolesOrCurrent(?UserInvitationRolesVO $roles): ?UserInvitationRolesVO
    {
        return $this->rolesAssigned ? ($this->roles === null ? null : UserInvitationRolesVO::from($this->roles)) : $roles;
    }
    public function rolesTryBuildInitial(ConstraintFailList $error): ?UserInvitationRolesVO
    {
        return  UserInvitationRolesVO::tryFrom($this->rolesAssigned ? $this->roles : null, $error);
    }
    public function roles(UserInvitationRolesVO|string|null $roles): static
    {
        $this->roles = $roles;
        $this->rolesAssigned = true;
        return $this;
    }
    public function getRoles(): ?string
    {
        return $this->roles instanceof UserInvitationRolesVO ? $this->roles->value() : $this->roles;
    }
    public function isRolesAssigned(): bool
    {
        return $this->rolesAssigned;
    }
    public function writeRolesTo(mixed $att): void
    {
        if ($this->rolesAssigned) {
            $att->roles($this->roles);
        }
    }
    public function readRolesFrom(mixed $att): void
    {
        if ($att->isRolesAssigned()) {
            $roles = $att->getRoles();
            $this->roles($roles);
        }
    }
    public function unsetRoles(): static
    {
        $this->rolesAssigned = false;
        return $this;
    }
    protected function withDefaultRoles(): void
    {
    }
    protected function withAssertedRolesRules(self $value, ConstraintFailList $errorsList): void
    {
        if ($value->rolesAssigned = $this->rolesAssigned) {
            $value->roles = UserInvitationRolesVO::tryFrom($this->roles, $errorsList);
        }
    }
}
